def solve(words):
    # Group words by their sorted character tuple
    groups = {}
    for w in words:
        key = tuple(sorted(w))
        groups.setdefault(key, []).append(w)
    # Sort each group's words alphabetically
    result = []
    for lst in groups.values():
        result.append(sorted(lst))
    # Sort groups by their first element (lexicographically)
    result.sort(key=lambda g: g[0] if g else '')
    return result

