def solve(matrix):
    """Return determinant of square integer matrix using Bareiss algorithm.
    Empty matrix has determinant 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    if n == 0:
        return 1
    # make a deep copy to avoid mutating input
    a = [row[:] for row in matrix]
    if n == 1:
        return a[0][0]
    sign = 1
    prev = 1
    for k in range(n-1):
        # pivot element
        if a[k][k] == 0:
            # find a row to swap
            swap = None
            for i in range(k+1, n):
                if a[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            a[k], a[swap] = a[swap], a[k]
            sign = -sign
        pivot = a[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
        prev = pivot
    return sign * a[n-1][n-1]

