def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses O(n log n) patience sorting method.
    """
    if not nums:
        return 0
    import bisect
    tails = []  # tails[i] = smallest possible tail of an inc subseq of length i+1
    for x in nums:
        # find position to insert x in tails
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

