def solve(a, x):
    """Return leftmost insertion index for x in sorted list a.
    Works for empty list and duplicates.
    """
    # Use binary search manually to avoid import
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

