    Standard in-place algorithm, returned as a list."""
    if isinstance(nums, (str, bytes)) or nums is None:
        raise TypeError("nums must be a list of integers")
    norm = []
    for x in nums:
        if isinstance(x, bool):
            norm.append(int(x))
        else:
            norm.append(x)
    a = norm
    n = len(a)
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i >= 0:
        j = n - 1
        while a[j] <= a[i]:
            j -= 1
        a[i], a[j] = a[j], a[i]
    a[i + 1:] = reversed(a[i + 1:])
    return a

